sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
	if (isLoading || newValue === '') {
		return;
	}

	var ga = new GlideAjax('x_1590365_shark_0.SharkUniversityUtils');
	ga.addParam('sysparm_name', 'validateTrainingDate');
	ga.addParam('sysparm_date_value', newValue);

	ga.getXMLAnswer(function (response) {
		if (!response) {
            return; 
        }

		var objResponse = JSON.parse(response);
		if (objResponse.isDuplicate) {
			g_form.clearValue('training_date');
			g_form.showFieldMsg('training_date', objResponse.msgExistingDate, 'error');
		}
	});

}
